mapper.select:
select id, person_id, title, dir, photo_count, bytes, cover_path, note, sort, hidden, mtime
from media_album
where id = #{id}

select id, root_id, album_id, seq, rel_path, bytes, w, h, is_big, hidden
from media_photo
where id = #{id}

select id, root_id, album_id, seq, rel_path, bytes, w, h, is_big, hidden
from media_photo
where album_id = #{albumId} and seq = #{seq}

select p.id, p.album_id, p.seq, p.rel_path, p.bytes, p.w, p.h, p.is_big, p.hidden
from media_photo p
where p.album_id = #{albumId}
order by p.seq asc
limit #{limit}

select count(*)
from media_album
where dir = #{dir} and id <> #{excludeId}
